// Read exact sources unchanged; output two additional opponent counts.
#define main original_main
#include "build-offline-flop.cpp"
#undef main
#include <cmath>
int main(){try{std::array<std::string,6>names={"hu","two","three","four","five","six"};std::array<U,6>den={1070190,966381570,792432887400ULL,587192769563400ULL,decimal("391070384529224400"),decimal("232686878794888518000")};const long double c[2][7]={{9.L/25840,-99.L/6460,539.L/2584,-1535.L/1292,113.L/34,-821.L/170,7.L/2},{2379.L/1683476,-26169.L/420869,3409651.L/4208690,-7300383.L/1683476,989099.L/88604,-6291447.L/443020,198677.L/26060}};std::vector<int>heroes;for(auto&p:fs::directory_iterator("data/flop-hu-v1"))if(p.path().extension()==".gz")heroes.push_back(std::stoi(p.path().filename().string()));std::sort(heroes.begin(),heroes.end());if(heroes.size()!=169)throw std::runtime_error("coverage");std::vector<Block>blocks;uint64_t states=0;
for(int h:heroes){std::array<B,6>src;uint32_t rows=0;for(int n=0;n<6;n++){src[n]=readgzip("data/flop-"+names[n]+"-v1/"+std::to_string(h)+".bin.gz");if(!n)rows=get(src[n],4);if(get(src[n],4)!=rows)throw std::runtime_error("alignment");}B raw;for(uint32_t i=0;i<rows;i++){long double p[2][6];uint32_t key=get(src[0],8+i*12);for(int n=0;n<6;n++){int w=n<2?4:n==5?16:8;size_t o=8+size_t(i)*(4+2*w);if(get(src[n],o)!=key)throw std::runtime_error("keys");U win=wide(src[n],o+4,w),tie=wide(src[n],o+4+w,w);p[0][n]=(long double)win/(long double)den[n];p[1][n]=(long double)(win+tie)/(long double)den[n];}int previous[2]={255,255};for(int j=0;j<2;j++){int values[2];for(int m=0;m<2;m++){long double v=c[j][0];bool zero=true,one=true;for(int n=0;n<6;n++){v+=c[j][n+1]*p[m][n];zero&=p[m][n]==0;one&=p[m][n]==1;}if(zero)v=0;if(one)v=1;v=std::clamp(v,0.L,p[m][5]);values[m]=std::min(previous[m],int(std::floor(v*255+.5L)));}values[0]=std::min(values[0],values[1]);for(int m=0;m<2;m++){raw.push_back(values[m]);previous[m]=values[m];}}}states+=rows;blocks.push_back({uint16_t(h),rows,uint32_t(raw.size()),zip(raw)});if(blocks.size()%40==0)std::cerr<<blocks.size()<<"/169\n";}
if(states!=1286792)throw std::runtime_error("states");B out={'N','I','N','1'};put(out,169,4);uint32_t offset=8+169*18;for(auto&b:blocks){put(out,b.hero,2);put(out,b.rows,4);put(out,offset,4);put(out,b.packed.size(),4);put(out,b.raw,4);offset+=b.packed.size();}for(auto&b:blocks)out.insert(out.end(),b.packed.begin(),b.packed.end());fs::create_directories("data/nine-v1");std::ofstream f("data/nine-v1/flop.bin",std::ios::binary);f.write((char*)out.data(),out.size());std::cout<<states<<" states, "<<out.size()<<" bytes\n";}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
